with q as (
 select * from (values
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-pccr-3228-classe-iii-01','Lei nº 3.228/2017 — promoção à Classe III','Um Oficial Investigador na Classe II já cumpriu 36 meses, obteve média de 85 pontos e completou 120 horas de capacitação. Para a promoção à Classe III, qual requisito específico adicional também é exigido pelo art. 11?','(A) Apenas prova oral.\n(B) Pós-graduação reconhecida pelo MEC, com mínimo de 360 horas, em área de interesse da Polícia Civil, e proposta de melhoria da atuação da unidade.\n(C) Doutorado obrigatório.\n(D) Proposta de melhoria da segurança pública estadual.\n(E) Cinco anos de exercício na Classe II.','B','A promoção à Classe III exige, além do núcleo comum, pós-graduação lato ou stricto sensu reconhecida pelo MEC, com carga mínima de 360 horas em área de interesse da Polícia Civil, e proposta de melhoria da atuação da unidade em que trabalha.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-pccr-3228-propostas-02','Lei nº 3.228/2017 — propostas de melhoria','Qual associação entre classe pretendida e proposta de melhoria está correta?','(A) Classe III: segurança pública estadual; Classe IV: unidade; Classe V: serviços da Polícia Civil.\n(B) Classe III: unidade; Classe IV: serviços da Polícia Civil; Classe V: segurança pública no Estado.\n(C) Classe III: serviços da Polícia Civil; Classe IV: segurança pública; Classe V: unidade.\n(D) Todas exigem apenas proposta da unidade.\n(E) Nenhuma classe exige proposta de melhoria.','B','O art. 11 diferencia a proposta: para Classe III, melhoria da atuação da unidade; para Classe IV, melhoria dos serviços da Polícia Civil; para Classe V, melhoria da segurança pública no Estado.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-pccr-titulacao-03','Lei nº 3.228/2017 — adicional de titulação','Um servidor apresenta título de doutorado expedido por instituição reconhecida pelo MEC. Qual percentual de adicional de titulação prevê o art. 6º, respeitado o teto legal?','(A) 7,5%.\n(B) 10%.\n(C) 15%.\n(D) 20%.\n(E) 25%.','D','O art. 6º prevê 20% por título de doutorado e estabelece teto máximo de 20% incidente sobre o vencimento básico.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-pccr-promocao-analise-04','Lei nº 3.228/2017 — comissão e homologação','De acordo com os arts. 9º e 10 da Lei nº 3.228/2017, qual é a divisão correta de atribuições no processo de promoção?','(A) A comissão homologa e o Secretário apenas publica.\n(B) O Conselho Superior concede diretamente e a comissão recorre.\n(C) A comissão de promoção analisa os processos e o Secretário homologa por ato específico.\n(D) A Corregedoria homologa e a comissão fiscaliza.\n(E) O Governador analisa individualmente todos os documentos.','C','O art. 9º atribui à comissão de promoção a análise dos processos; o art. 10 determina que a homologação seja feita por ato específico do Secretário de Estado da Polícia Civil.')
 ) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation)
